        children: "function TabsList({ children, onKeyDown, ...props }: TabsListProps) {
  return (
    <div
      role="tablist"
      {...props}
      onKeyDown={(event) => {
        onKeyDown?.(event);

        if (event.defaultPrevented) {
          return;
        }

        const keyToDirection: Record<string, 1 | -1> = {
          ArrowRight: 1,
          ArrowDown: 1,
          ArrowLeft: -1,
          ArrowUp: -1,
        };

        const direction = keyToDirection[event.key];
        const currentTarget = event.target;

        if (!(currentTarget instanceof HTMLButtonElement)) {
          return;
        }

        const tabs = getEnabledTabs(event.currentTarget);
        const currentIndex = tabs.indexOf(currentTarget);

        if (event.key === 'Home') {
          event.preventDefault();
          tabs[0]?.focus();
          return;
        }

        if (event.key === 'End') {
          event.preventDefault();
          tabs[tabs.length - 1]?.focus();
          return;
        }

        if (!direction || currentIndex === -1) {
          return;
        }

        event.preventDefault();

        const nextIndex = (currentIndex + direction + tabs.length) % tabs.length;
        tabs[nextIndex]?.focus();
        tabs[nextIndex]?.click();
      }}
    >
      {children}
    </div>
  );
}
